```typescript
export interface NewMember { handle: string; contact: string; secret: string; fullName: string; }
export interface Member extends NewMember { id: string; }
export class MemberDirectory {
  private readonly members: Member[] = [];
  private nextId = 1;
  create(input: NewMember): Member {
    const value = { ...input, handle: input.handle.trim(), contact: input.contact.trim(), fullName: input.fullName.trim() };
    const emailParts = value.contact.split('@');
    if (!value.handle || !value.fullName || emailParts.length !== 2 || !emailParts[0] || !emailParts[1]) throw new Error('Invalid member');
    if (value.secret.length < 6) throw new Error('Secret too short');
    if (this.members.some(m => m.handle === value.handle)) throw new Error('Duplicate handle');
    const member = { ...value, id: `m${this.nextId++}` };
    this.members.push(member);
    return { ...member };
  }
  find(handle: string): Member | undefined { const member = this.members.find(m => m.handle.toLowerCase() === handle.toLowerCase()); return member && { ...member }; }
  list(): Member[] { return this.members.map(m => ({ ...m })); }
}
```

