import { MemberDirectory, NewMember } from './solution';

function assert(value: boolean, message: string): void { if (!value) throw new Error(message); }
function equal(actual: unknown, expected: unknown, message: string): void { if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`); }
function deepEqual(actual: unknown, expected: unknown, message: string): void { if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: ${JSON.stringify(actual)}`); }
function throws(action: () => unknown, message: string): void { let didThrow = false; try { action(); } catch { didThrow = true; } if (!didThrow) throw new Error(message); }

const directory = new MemberDirectory();
deepEqual(directory.list(), [], 'empty directory valid');
equal(directory.find('nobody'), undefined, 'find on empty directory');

throws(() => directory.create({ handle: ' ', contact: 'a@b', secret: '123456', fullName: 'A' }), 'blank handle rejected');
throws(() => directory.create({ handle: 'a', contact: 'bad', secret: '123456', fullName: 'A' }), 'contact without at-sign rejected');
throws(() => directory.create({ handle: 'a', contact: '@b', secret: '123456', fullName: 'A' }), 'contact missing left side rejected');
throws(() => directory.create({ handle: 'a', contact: 'a@', secret: '123456', fullName: 'A' }), 'contact missing right side rejected');
throws(() => directory.create({ handle: 'a', contact: 'a@b@c', secret: '123456', fullName: 'A' }), 'contact with multiple at-signs rejected');
throws(() => directory.create({ handle: 'a', contact: 'a@b', secret: '12345', fullName: 'A' }), 'short secret rejected');
throws(() => directory.create({ handle: 'a', contact: 'a@b', secret: '123456', fullName: ' ' }), 'blank full name rejected');

const input: NewMember = { handle: '  Forge  ', contact: '  forge@example.com  ', secret: '123456', fullName: '  Navneet Prabhakar  ' };
const first = directory.create(input);
deepEqual(first, { id: 'm1', handle: 'Forge', contact: 'forge@example.com', secret: '123456', fullName: 'Navneet Prabhakar' }, 'fields trimmed and first successful id is m1');
input.handle = 'mutated';
first.handle = 'corrupt';
equal(directory.find('FORGE')?.handle, 'Forge', 'create copies input and find is case insensitive');
throws(() => directory.create({ handle: 'fOrGe', contact: 'other@example.com', secret: 'abcdef', fullName: 'Other' }), 'handles unique case insensitively');

const second = directory.create({ handle: 'Grace', contact: 'grace@example.com', secret: 'abcdef', fullName: 'Grace Hopper' });
equal(second.id, 'm2', 'failed creations do not consume ids');
deepEqual(directory.list().map(member => member.id), ['m1', 'm2'], 'list preserves creation order');
const found = directory.find('grace');
assert(found !== undefined, 'known member found');
if (found) found.fullName = 'corrupt';
const listed = directory.list();
listed[0].contact = 'corrupt';
listed.pop();
equal(directory.find('Grace')?.fullName, 'Grace Hopper', 'find result does not alias internal state');
equal(directory.find('Forge')?.contact, 'forge@example.com', 'list members do not alias internal state');
equal(directory.list().length, 2, 'list array does not alias internal state');

